<template>
  <div>
    <div class="d-flex align-center justify-space-between flex-wrap ga-3 mb-5"><div><h2 class="text-h5">Dashboard Templates</h2><p class="text-body-2 mt-1">Choose the cards and priorities for each role. Assign a template under Roles.</p></div><div class="d-flex ga-2 flex-wrap"><v-btn v-if="canEdit" variant="tonal" :loading="loading" @click="addPresets">Add starter templates</v-btn><v-btn v-if="canEdit" color="primary" prepend-icon="mdi-plus" @click="edit()">New template</v-btn></div></div>
    <v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{ error }}</v-alert>
    <v-progress-linear v-if="loading" indeterminate />
    <v-alert v-if="!loading && !templates.length" variant="tonal" color="primary">Start with Admin Overview, Sales Focus and Work Focus, or create your own template.</v-alert>
    <v-row><v-col v-for="template in templates" :key="template.id" cols="12" md="6" lg="4"><v-card rounded="xl" class="pa-5 h-100"><div class="d-flex align-center ga-2"><v-icon color="primary">mdi-view-dashboard-outline</v-icon><h3 class="text-h6">{{ template.name }}</h3></div><p class="text-body-2 text-medium-emphasis my-3">{{ template.description }}</p><v-chip size="small" variant="tonal" class="mb-3">{{ template.record_scope==='assigned'?'Assigned to logged-in staff':'Records allowed by role' }}</v-chip><div class="d-flex flex-wrap ga-2 mb-4"><v-chip v-for="id in template.widgets" :key="id" size="small" variant="outlined">{{ title(id) }}</v-chip><span v-if="!template.widgets.length" class="text-caption">No cards selected</span></div><div class="d-flex ga-2"><v-btn size="small" variant="tonal" @click="edit(template)">{{ canEdit?'Edit / preview':'View' }}</v-btn><v-btn v-if="canEdit" size="small" variant="text" @click="edit({...template,id:null,name:template.name+' copy'})">Duplicate</v-btn><v-btn v-if="auth.can('settings','delete')" size="small" color="error" variant="text" @click="deleting=template">Delete</v-btn></div></v-card></v-col></v-row>
    <v-dialog v-model="dialog" max-width="1100" :persistent="saving"><v-card rounded="xl"><v-card-title class="pa-6">{{ form.id?'Edit dashboard template':'New dashboard template' }}</v-card-title><v-card-text><v-row><v-col cols="12" md="7"><v-select v-if="!form.id && canEdit" :items="presets" item-title="name" return-object label="Start from a design" variant="outlined" @update:model-value="usePreset" /><v-text-field v-model="form.name" label="Template name *" variant="outlined" maxlength="100" :disabled="!canEdit" /><v-textarea v-model="form.description" label="Description" variant="outlined" rows="2" maxlength="500" :disabled="!canEdit" /><v-select v-model="form.record_scope" :items="[{title:'Records allowed by role',value:'accessible'},{title:'Assigned to logged-in staff only',value:'assigned'}]" label="Record visibility" variant="outlined" :disabled="!canEdit" /><h3 class="text-subtitle-1 mb-2">Cards to show</h3><div v-for="widget in orderedWidgets" :key="widget.id" class="d-flex align-center ga-2 border-b py-2"><v-checkbox :model-value="form.widgets.includes(widget.id)" @update:model-value="toggle(widget.id,$event)" :disabled="!canEdit" hide-details density="compact" :aria-label="widget.title" /><div class="flex-grow-1"><strong>{{ widget.title }}</strong><p class="text-caption text-medium-emphasis">{{ widget.description }}</p></div><template v-if="form.widgets.includes(widget.id)"><v-btn icon="mdi-chevron-up" variant="text" size="x-small" :disabled="!canEdit || form.widgets.indexOf(widget.id)===0" aria-label="Move card earlier" @click="move(widget.id,-1)" /><v-btn icon="mdi-chevron-down" variant="text" size="x-small" :disabled="!canEdit || form.widgets.indexOf(widget.id)===form.widgets.length-1" aria-label="Move card later" @click="move(widget.id,1)" /></template></div></v-col><v-col cols="12" md="5"><div class="template-preview pa-4 rounded-xl"><h3 class="text-h6">{{ form.name || 'Dashboard preview' }}</h3><p class="text-caption mb-4">Cards appear in this order. A staff member sees only cards permitted by their role.</p><div v-for="id in form.widgets" :key="id" class="bg-surface rounded-xl pa-4 mb-3"><div class="d-flex ga-2 align-center"><v-icon color="primary" size="20">{{ widgets.find(widget=>widget.id===id)?.icon }}</v-icon><strong class="text-body-2">{{ title(id) }}</strong></div><v-skeleton-loader type="text" class="mt-2" /></div><p v-if="!form.widgets.length">Select cards to build the dashboard.</p></div></v-col></v-row><v-alert v-if="dialogError" type="error" variant="tonal" class="mt-4">{{ dialogError }}</v-alert></v-card-text><v-card-actions class="pa-6"><v-spacer /><v-btn :disabled="saving" @click="dialog=false">Cancel</v-btn><v-btn v-if="canEdit" color="primary" variant="flat" :loading="saving" @click="save">Save template</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!deleting" @update:model-value="value=>{if(!value)deleting=null}" max-width="450"><v-card rounded="xl" class="pa-6"><h3 class="text-h6">Delete {{ deleting?.name }}?</h3><p class="my-3">Templates used by a role cannot be deleted.</p><div class="d-flex justify-end ga-2"><v-btn @click="deleting=null">Cancel</v-btn><v-btn color="error" :loading="saving" @click="remove">Delete</v-btn></div></v-card></v-dialog>
  </div>
</template>
<script setup>
import {useAuthStore} from '~/stores/auth';import {useUIStore} from '~/stores/ui';
const auth=useAuthStore(),ui=useUIStore(),{$api}=useNuxtApp();
const canEdit=computed(()=>auth.can('settings','write'));
const templates=ref([]),widgets=ref([]),presets=ref([]),loading=ref(false),saving=ref(false),error=ref(''),dialogError=ref(''),dialog=ref(false),deleting=ref(null);
const form=reactive({id:null,name:'',description:'',record_scope:'accessible',widgets:[]});
const title=id=>widgets.value.find(widget=>widget.id===id)?.title || id;
const orderedWidgets=computed(()=>[...form.widgets.map(id=>widgets.value.find(widget=>widget.id===id)).filter(Boolean),...widgets.value.filter(widget=>!form.widgets.includes(widget.id))]);
async function load(){loading.value=true;try{const data=(await $api.get('/dashboard/templates')).data.data;templates.value=data.templates;widgets.value=data.widgets;presets.value=data.presets;}catch(e){error.value=e.response?.data?.message || 'Unable to load templates.';}finally{loading.value=false;}}
function edit(template){Object.assign(form,template?{...template,widgets:[...template.widgets]}:{id:null,name:'',description:'',record_scope:'accessible',widgets:[]});dialogError.value='';dialog.value=true;}
function usePreset(preset){if(preset)Object.assign(form,{...preset,widgets:[...preset.widgets]});}
function toggle(id,value){form.widgets=value?[...form.widgets,id]:form.widgets.filter(item=>item!==id);}
function move(id,direction){const index=form.widgets.indexOf(id),next=index+direction;if(next<0 || next>=form.widgets.length)return;[form.widgets[index],form.widgets[next]]=[form.widgets[next],form.widgets[index]];}
async function save(){saving.value=true;dialogError.value='';try{await $api[form.id?'put':'post'](form.id?`/dashboard/templates/${form.id}`:'/dashboard/templates',{name:form.name,description:form.description,record_scope:form.record_scope,widgets:form.widgets});dialog.value=false;await load();ui.showSuccess('Dashboard template saved.');}catch(e){dialogError.value=e.response?.data?.message || 'Unable to save template.';}finally{saving.value=false;}}
async function addPresets(){error.value='';loading.value=true;try{await $api.post('/dashboard/templates/presets');await load();}catch(e){error.value=e.response?.data?.message || 'Unable to add starter templates.';}finally{loading.value=false;}}
async function remove(){saving.value=true;try{await $api.delete(`/dashboard/templates/${deleting.value.id}`);deleting.value=null;await load();}catch(e){deleting.value=null;error.value=e.response?.data?.message || 'Unable to delete template.';}finally{saving.value=false;}}
onMounted(load);
</script>
<style scoped>.template-preview{background:rgba(var(--v-theme-primary),.06);position:sticky;top:16px}</style>
